/**
 * Close ontology, part 1: foundations (REA), organization, ledger structure, account classes,
 * financial statements, journal entries and periods.
 */
import type { OntologyClass } from '../../../core/ontology/types';

type C = OntologyClass;
const c = (o: C): C => o;

export const LEDGER_CLASSES: C[] = [
  // ------------------------------------------------------------------ REA foundations
  c({ id: 'tie:Thing', label: 'Thing', group: 'foundations', parents: [], abstract: true, definition: 'The root of the close ontology; everything Tieout reasons about is a Thing.', whyItMatters: 'A single root keeps the class hierarchy connected so every term can be explained by its lineage.', example: 'A journal entry, a vendor and a reconciliation are all Things.' }),
  c({ id: 'tie:EconomicResource', label: 'Economic resource', group: 'foundations', parents: ['tie:Thing'], abstract: true, rea: 'Resource', definition: 'Something of value that the business controls and wants to plan, monitor and control (REA "Resource").', whyItMatters: 'Assets on the balance sheet are measurements of economic resources; REA keeps the ledger tied to what the business actually has.', example: 'Cash in the operating bank account; sensor inventory; a spectrometer.', mappings: [{ scheme: 'REA', ref: 'EconomicResource', match: 'exact' }], citations: ['mccarthy1982', 'iso15944-4'] }),
  c({ id: 'tie:EconomicEvent', label: 'Economic event', group: 'foundations', parents: ['tie:Thing'], abstract: true, rea: 'Event', definition: 'An occurrence that changes economic resources: a sale, a purchase, a cash receipt or disbursement, the use of an asset over time.', whyItMatters: 'Journal entries are representations of economic events; if the event did not happen the entry fails the existence/occurrence assertion.', example: 'Shipping 400 sensor kits to a customer is a sale event; the customer paying is a cash-receipt event.', mappings: [{ scheme: 'REA', ref: 'EconomicEvent', match: 'exact' }], citations: ['mccarthy1982', 'geerts2002'] }),
  c({ id: 'tie:EconomicAgent', label: 'Economic agent', group: 'foundations', parents: ['tie:Thing'], abstract: true, rea: 'Agent', definition: 'A person or organization that participates in economic events — as provider or receiver of resources, or as the one accountable.', whyItMatters: 'Controls are about agents: who prepared, who approved, who received the cash. Segregation of duties is a rule about agents.', example: 'A vendor, a customer, an employee, a legal entity, and an AI agent acting for a staff accountant.', mappings: [{ scheme: 'REA', ref: 'EconomicAgent', match: 'exact' }], citations: ['mccarthy1982'] }),
  c({ id: 'tie:Commitment', label: 'Commitment', group: 'foundations', parents: ['tie:Thing'], abstract: true, rea: 'Commitment', definition: 'A promise to perform an economic event in the future (extended REA), such as a purchase order or a customer contract.', whyItMatters: 'Commitments are early evidence of liabilities and revenue: a received-but-unbilled purchase order is the classic unrecorded liability.', example: 'PO-2026-0412 commits Bramblewood to pay for 400 sensor modules on delivery.', mappings: [{ scheme: 'REA', ref: 'Commitment', match: 'exact' }], citations: ['geerts2002', 'iso15944-4'] }),
  c({ id: 'tie:InternalAgent', label: 'Internal agent', group: 'organization', parents: ['tie:EconomicAgent'], definition: 'An agent inside the reporting entity, accountable for events on its behalf.', whyItMatters: 'Only internal agents can prepare or approve entries; their roles drive permissions and SoD.', example: 'Sam Rivera, Staff Accountant.', rea: 'Agent', citations: ['mccarthy1982'] }),
  c({ id: 'tie:ExternalAgent', label: 'External agent', group: 'organization', parents: ['tie:EconomicAgent'], definition: 'A counterparty outside the entity: vendors, customers, banks, tax authorities.', whyItMatters: 'Text that comes from external agents (vendor names, bank memos) is untrusted data — it must never steer an AI agent.', example: 'Cumulus Hosting Co. sending an invoice.', rea: 'Agent' }),
  c({ id: 'tie:LegalEntity', label: 'Legal entity', group: 'organization', parents: ['tie:InternalAgent'], definition: 'A company that keeps its own books and files its own returns; the unit that a set of financial statements describes.', whyItMatters: 'Each entity has its own functional currency, periods and materiality; consolidation adds the entities together and eliminates what they owe each other.', example: 'Bramblewood Labs, Inc. (US, USD) and Bramblewood Labs Ltd (UK, GBP).', synonyms: ['entity', 'company', 'subsidiary'], mappings: [{ scheme: 'FIBO', ref: 'fibo-be-le-lp:LegalEntity', match: 'close' }, { scheme: 'XBRL-GL', ref: 'gl-bus:organizationIdentifiers', match: 'related' }], citations: ['fibo', 'xbrl-gl'], properties: [{ name: 'code', label: 'Code', range: 'string', required: true, description: 'Short entity code, e.g. BWL-US' }, { name: 'functionalCurrency', label: 'Functional currency', range: 'string', required: true, description: 'ISO 4217 code of the primary economic environment' }] }),
  c({ id: 'tie:EliminationEntity', label: 'Elimination entity', group: 'organization', parents: ['tie:LegalEntity'], definition: 'A consolidation-only ledger that holds elimination and consolidation adjustments; it never trades.', whyItMatters: 'Keeping eliminations in their own ledger leaves each legal entity’s books untouched and auditable.', example: 'BWL-ELIM holds the entry that removes the US payable and UK receivable for R&D services.', citations: ['asc810'] }),
  c({ id: 'tie:Vendor', label: 'Vendor', group: 'organization', parents: ['tie:ExternalAgent'], definition: 'A supplier the entity buys goods or services from and pays through accounts payable.', whyItMatters: 'Vendor history is the strongest signal for coding new spend, and vendor-level patterns reveal missing invoices and duplicate payments.', example: 'Atlas & Pike LLP bills legal fees every month.', synonyms: ['supplier', 'payee'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:identifierReference (vendor)', match: 'related' }] }),
  c({ id: 'tie:Customer', label: 'Customer', group: 'organization', parents: ['tie:ExternalAgent'], definition: 'A party that buys from the entity and pays through accounts receivable.', whyItMatters: 'Customer receipts must be applied to the right invoices; unapplied cash distorts AR aging and the AR tie-out.', example: 'Aldergrove Utilities pays its annual platform subscription.' }),
  c({ id: 'tie:Employee', label: 'Employee', group: 'organization', parents: ['tie:InternalAgent'], definition: 'A person employed by the entity; the payroll subledger records their compensation.', whyItMatters: 'Payroll is usually the largest expense; days worked but not yet paid at month-end must be accrued.', example: 'An R&D engineer paid biweekly.' }),
  c({ id: 'tie:Currency', label: 'Currency', group: 'organization', parents: ['tie:Thing'], definition: 'A medium of exchange identified by an ISO 4217 code, with a number of minor units (USD has 2).', whyItMatters: 'Every amount is in some currency; mixing currencies without conversion is a silent, material error.', example: 'USD, GBP, EUR.', mappings: [{ scheme: 'FIBO', ref: 'fibo-fnd-acc-cur:Currency', match: 'exact' }], citations: ['fibo'] }),
  c({ id: 'tie:MoneyAmount', label: 'Money amount', group: 'organization', parents: ['tie:Thing'], definition: 'A quantity of a currency, stored exactly as integer minor units (cents, pence).', whyItMatters: 'Binary floating point cannot represent 0.10 exactly; the ledger stores integers so that debits always equal credits to the penny.', example: '$1,236.40 is stored as 123640 cents.', properties: [{ name: 'amountMinor', label: 'Amount (minor units)', range: 'money', required: true, description: 'Integer amount in minor units' }, { name: 'currency', label: 'Currency', range: 'string', required: true, description: 'ISO 4217 code' }], mappings: [{ scheme: 'FIBO', ref: 'fibo-fnd-acc-cur:MonetaryAmount', match: 'close' }, { scheme: 'XBRL-GL', ref: 'gl-cor:amount', match: 'close' }] }),
  c({ id: 'tie:Dimension', label: 'Dimension', group: 'organization', parents: ['tie:Thing'], abstract: true, definition: 'An analytic tag on a journal line — department, location, class or project — used to slice results without multiplying accounts.', whyItMatters: 'Budgets and flux analysis are usually by department; a missing department makes a variance unexplainable.', example: 'Department = R&D on a cloud hosting charge.', synonyms: ['segment', 'tag', 'analysis code'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:measurable / gl-bus:measurableCode', match: 'related' }] }),
  c({ id: 'tie:Department', label: 'Department', group: 'organization', parents: ['tie:Dimension'], definition: 'The organizational unit responsible for a cost or revenue (R&D, Sales, Marketing, G&A…).', whyItMatters: 'Operating expenses are presented by function (R&D, S&M, G&A) on the income statement, derived from the department tag.', example: 'Marketing owns the ConfabCon sponsorship.', synonyms: ['cost center'] }),
  c({ id: 'tie:Location', label: 'Location', group: 'organization', parents: ['tie:Dimension'], definition: 'The site or region a transaction relates to.', whyItMatters: 'Location drives tax, rent allocation and regional reporting.', example: 'US-SF, UK-LDN.' }),
  c({ id: 'tie:ProductClass', label: 'Class / product line', group: 'organization', parents: ['tie:Dimension'], definition: 'The product or service line a transaction relates to.', whyItMatters: 'Gross margin by product line depends on revenue and cost of revenue carrying the same class.', example: 'Platform, Hardware, Services.', synonyms: ['class'] }),
  c({ id: 'tie:Project', label: 'Project', group: 'organization', parents: ['tie:Dimension'], definition: 'A time-bound initiative that costs are tracked against.', whyItMatters: 'Project tags explain one-off spikes in flux (e.g. a data-pipeline migration).', example: 'PRJ-PIPELINE.' }),

  // ------------------------------------------------------------------ ledger structure
  c({ id: 'tie:Ledger', label: 'Ledger', group: 'ledger', parents: ['tie:Thing'], abstract: true, definition: 'An ordered record of accounting entries.', whyItMatters: 'The general ledger is the book of record; subledgers hold the detail behind its control accounts.', example: 'The BWL-US general ledger.' }),
  c({ id: 'tie:GeneralLedger', label: 'General ledger', group: 'ledger', parents: ['tie:Ledger'], definition: 'The complete set of accounts and posted journal entries of one legal entity, from which the trial balance and financial statements are produced.', whyItMatters: 'Everything in the close ends up here; anything not in the GL is not in the financial statements.', example: 'The trial balance of BWL-US at 30 Sep 2026 sums the GL by account.', synonyms: ['GL', 'book of record'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:accountingEntries', match: 'close' }], citations: ['xbrl-gl'] }),
  c({ id: 'tie:Subledger', label: 'Subledger', group: 'subledgers', parents: ['tie:Ledger'], abstract: true, definition: 'A detailed ledger for one type of transaction (payables, receivables, cash, cards, fixed assets, prepaids, payroll) whose total must equal a GL control account.', whyItMatters: 'If the subledger total and the control account disagree, either the detail or the GL is wrong — that is what a tie-out finds.', example: 'The AP subledger lists open bills by vendor; its total equals account 2000.', synonyms: ['sub-ledger', 'subsidiary ledger'] }),
  c({ id: 'tie:ChartOfAccounts', label: 'Chart of accounts', group: 'ledger', parents: ['tie:Thing'], definition: 'The structured list of accounts a company records transactions in, organized as a hierarchy that rolls up to financial-statement lines.', whyItMatters: 'A clean chart of accounts is what makes automated coding, flux and reporting possible.', example: '1010 Cash – Operating rolls up to "Cash and cash equivalents" on the balance sheet.', synonyms: ['COA'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:account', match: 'related' }] }),
  c({ id: 'tie:Account', label: 'Account', group: 'accounts', parents: ['tie:Thing'], abstract: true, definition: 'A named bucket in the ledger that accumulates debits and credits for one kind of asset, liability, equity, revenue or expense.', whyItMatters: 'Choosing the right account (classification) decides which line of the financial statements an amount lands on.', example: '6150 Software subscriptions.', properties: [{ name: 'code', label: 'Account code', range: 'string', required: true, description: 'Account number, e.g. 6150' }, { name: 'normalBalance', label: 'Normal balance', range: 'enum', enumValues: ['debit', 'credit'], required: true, description: 'Side that increases the account' }], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:accountMainID', match: 'close' }], citations: ['xbrl-gl', 'pacioli1494'] }),
  c({ id: 'tie:ControlAccount', label: 'Control account', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'A GL account whose balance is the total of a subledger (e.g. accounts payable, accounts receivable).', whyItMatters: 'Posting directly to a control account bypasses the subledger and breaks the tie-out; such entries need extra approval.', example: '2000 Accounts payable is controlled by the AP subledger.' }),
  c({ id: 'tie:ContraAccount', label: 'Contra account', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'An account that reduces a related account and therefore carries the opposite normal balance.', whyItMatters: 'Contra accounts present gross and net amounts (equipment cost minus accumulated depreciation) without losing history.', example: '1590 Accumulated depreciation is a credit-balance asset account.' }),
  c({ id: 'tie:AssetAccount', label: 'Asset', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'A present economic resource controlled by the entity as a result of past events. Normal balance: debit.', whyItMatters: 'Overstated assets are the classic way results are inflated; existence and valuation are the key assertions.', example: 'Cash, receivables, prepaid expenses, equipment.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:Assets', match: 'exact' }], citations: ['conceptual-framework'] }),
  c({ id: 'tie:LiabilityAccount', label: 'Liability', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'A present obligation to transfer economic resources as a result of past events. Normal balance: credit.', whyItMatters: 'Understated liabilities (unrecorded bills, missed accruals) are the most common close error; completeness is the key assertion.', example: 'Accounts payable, accrued expenses, deferred revenue.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:Liabilities', match: 'exact' }], citations: ['conceptual-framework'] }),
  c({ id: 'tie:EquityAccount', label: 'Equity', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'The residual interest in assets after deducting liabilities. Normal balance: credit.', whyItMatters: 'Assets = Liabilities + Equity is the accounting equation every balanced entry preserves.', example: 'Common stock, retained earnings, cumulative translation adjustment.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:StockholdersEquity', match: 'exact' }], citations: ['conceptual-framework', 'pacioli1494'] }),
  c({ id: 'tie:RevenueAccount', label: 'Revenue', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'Increases in assets or decreases in liabilities from delivering goods or services to customers. Normal balance: credit.', whyItMatters: 'Revenue is the most scrutinized number; ASC 606 decides when it is earned.', example: 'Subscription revenue recognized ratably each month.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:Revenues', match: 'exact' }], citations: ['asc606', 'conceptual-framework'] }),
  c({ id: 'tie:ExpenseAccount', label: 'Expense', group: 'accounts', parents: ['tie:Account'], abstract: true, definition: 'Decreases in assets or increases in liabilities from delivering goods or services or running the business. Normal balance: debit.', whyItMatters: 'Expenses must land in the period they are incurred (cut-off) and in the right function (classification).', example: 'Cloud hosting, salaries, legal fees.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:CostsAndExpenses', match: 'close' }], citations: ['conceptual-framework'] }),

  // assets
  c({ id: 'tie:CurrentAsset', label: 'Current asset', group: 'accounts', parents: ['tie:AssetAccount'], abstract: true, definition: 'An asset expected to be realized within twelve months.', whyItMatters: 'Working capital (current assets minus current liabilities) is a covenant and liquidity measure.', example: 'Cash, receivables, prepaids.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AssetsCurrent', match: 'exact' }] }),
  c({ id: 'tie:CashAndCashEquivalents', label: 'Cash and cash equivalents', group: 'accounts', parents: ['tie:CurrentAsset', 'tie:ControlAccount'], rea: 'Resource', definition: 'Money in bank accounts and highly liquid investments with original maturities of three months or less.', whyItMatters: 'Cash is reconciled to bank statements every month; an unreconciled cash account is a red flag for auditors.', example: '1010 Cash – First Harbor operating account.', synonyms: ['cash', 'bank'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:CashAndCashEquivalentsAtCarryingValue', match: 'exact' }] }),
  c({ id: 'tie:AccountsReceivable', label: 'Accounts receivable', group: 'accounts', parents: ['tie:CurrentAsset', 'tie:ControlAccount'], rea: 'Resource', definition: 'Amounts customers owe for goods or services already delivered and invoiced.', whyItMatters: 'Receivables must tie to the AR aging; old unpaid balances may need an allowance.', example: '1100 Accounts receivable.', synonyms: ['AR', 'trade receivables'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccountsReceivableNetCurrent', match: 'close' }] }),
  c({ id: 'tie:AllowanceForCreditLosses', label: 'Allowance for credit losses', group: 'accounts', parents: ['tie:CurrentAsset', 'tie:ContraAccount'], definition: 'A contra-asset estimating receivables that will not be collected.', whyItMatters: 'Valuation assertion: receivables are presented at the amount expected to be collected.', example: '1150 Allowance for doubtful accounts.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccountsReceivableAllowanceForCreditLossCurrent', match: 'exact' }] }),
  c({ id: 'tie:InventoryAsset', label: 'Inventory', group: 'accounts', parents: ['tie:CurrentAsset'], rea: 'Resource', definition: 'Goods held for sale or materials to be consumed in production.', whyItMatters: 'Received-not-invoiced goods increase inventory and a liability before the bill arrives.', example: '1300 Inventory – sensor kits.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:InventoryNet', match: 'exact' }], signals: { keywords: ['components', 'modules', 'sensor', 'parts', 'enclosures'], mcc: ['5065'] } }),
  c({ id: 'tie:PrepaidExpenseAsset', label: 'Prepaid expense', group: 'accounts', parents: ['tie:CurrentAsset'], definition: 'Cash paid in advance for goods or services to be received later; expensed (amortized) as the benefit is consumed.', whyItMatters: 'If the monthly amortization is missed, expenses are understated and the asset is overstated.', example: '1220 Prepaid software: a $54,000 annual CRM contract amortized $4,500 per month.', synonyms: ['prepaid', 'prepayment', 'deferred expense'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:PrepaidExpenseCurrent', match: 'exact' }], citations: ['asc340'] }),
  c({ id: 'tie:VendorReceivable', label: 'Vendor receivable', group: 'accounts', parents: ['tie:CurrentAsset'], definition: 'An amount a vendor owes back to the entity, e.g. after an overpayment or duplicate payment.', whyItMatters: 'A duplicate payment is an asset until the refund arrives; leaving it in AP hides it.', example: '1250 Other receivables – vendor refunds due.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:OtherReceivablesNetCurrent', match: 'close' }] }),
  c({ id: 'tie:IntercompanyReceivable', label: 'Intercompany receivable', group: 'accounts', parents: ['tie:CurrentAsset', 'tie:ControlAccount'], definition: 'An amount another entity in the same group owes this entity.', whyItMatters: 'Must equal the counterparty’s intercompany payable (after currency conversion) and is eliminated on consolidation.', example: '1400 Due from BWL-US in the UK ledger.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:DueFromRelatedPartiesCurrent', match: 'close' }], citations: ['asc810'] }),
  c({ id: 'tie:NonCurrentAsset', label: 'Non-current asset', group: 'accounts', parents: ['tie:AssetAccount'], abstract: true, definition: 'An asset expected to provide benefit beyond twelve months.', whyItMatters: 'Long-lived assets are capitalized and depreciated rather than expensed.', example: 'Lab equipment.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AssetsNoncurrent', match: 'exact' }] }),
  c({ id: 'tie:PropertyPlantEquipment', label: 'Property, plant & equipment', group: 'accounts', parents: ['tie:NonCurrentAsset'], rea: 'Resource', definition: 'Tangible long-lived assets used in operations, recorded at cost and depreciated over their useful life.', whyItMatters: 'Items above the capitalization threshold expensed by mistake understate assets and overstate expenses.', example: '1520 Lab equipment: a $14,250 spectrometer.', synonyms: ['PP&E', 'fixed assets', 'capex'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:PropertyPlantAndEquipmentGross', match: 'exact' }], citations: ['asc360'], signals: { keywords: ['spectrometer', 'oscilloscope', 'laptop', 'workstation', 'server rack', 'equipment', 'furniture'], mcc: ['5045', '5732', '5047', '5021'] } }),
  c({ id: 'tie:AccumulatedDepreciation', label: 'Accumulated depreciation', group: 'accounts', parents: ['tie:NonCurrentAsset', 'tie:ContraAccount'], definition: 'The total depreciation recognized to date on PP&E; a contra-asset with a credit balance.', whyItMatters: 'Accumulated depreciation may never exceed cost minus salvage value.', example: '1590 Accumulated depreciation.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccumulatedDepreciationDepletionAndAmortizationPropertyPlantAndEquipment', match: 'exact' }], citations: ['asc360'] }),
  c({ id: 'tie:RightOfUseAsset', label: 'Right-of-use asset', group: 'leases', parents: ['tie:NonCurrentAsset'], definition: 'A lessee’s right to use a leased asset over the lease term (ASC 842).', whyItMatters: 'Operating leases sit on the balance sheet since ASC 842; the asset and liability must be remeasured consistently.', example: '1610 ROU asset – San Francisco office lease.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:OperatingLeaseRightOfUseAsset', match: 'exact' }], citations: ['asc842'] }),

  // liabilities
  c({ id: 'tie:CurrentLiability', label: 'Current liability', group: 'accounts', parents: ['tie:LiabilityAccount'], abstract: true, definition: 'An obligation due within twelve months.', whyItMatters: 'Completeness of current liabilities is what accrual work protects.', example: 'Accounts payable, accrued expenses.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:LiabilitiesCurrent', match: 'exact' }] }),
  c({ id: 'tie:AccountsPayable', label: 'Accounts payable', group: 'accounts', parents: ['tie:CurrentLiability', 'tie:ControlAccount'], definition: 'Amounts owed to vendors for invoices received and approved but not yet paid.', whyItMatters: 'AP must tie to the open-bill aging; a debit balance on a vendor often means a duplicate payment.', example: '2000 Accounts payable.', synonyms: ['AP', 'trade payables'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccountsPayableCurrent', match: 'exact' }] }),
  c({ id: 'tie:AccruedLiabilities', label: 'Accrued liabilities', group: 'accounts', parents: ['tie:CurrentLiability'], definition: 'Expenses incurred but not yet invoiced or paid, recognized by an accrual entry.', whyItMatters: 'The accrual basis requires expenses in the period incurred, invoice or not.', example: '2110 Accrued expenses – legal services received in September, billed in October.', synonyms: ['accruals', 'accrued expenses'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccruedLiabilitiesCurrent', match: 'exact' }], citations: ['conceptual-framework', 'asc450'] }),
  c({ id: 'tie:AccruedPayroll', label: 'Accrued payroll', group: 'accounts', parents: ['tie:AccruedLiabilities'], definition: 'Wages earned by employees but not yet paid at period end.', whyItMatters: 'With biweekly pay, up to nine working days of wages can be unpaid at month-end.', example: '2120 Accrued payroll.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:EmployeeRelatedLiabilitiesCurrent', match: 'close' }] }),
  c({ id: 'tie:CreditCardPayable', label: 'Credit card payable', group: 'accounts', parents: ['tie:CurrentLiability', 'tie:ControlAccount'], definition: 'Amounts owed to the corporate card issuer for card spend not yet settled.', whyItMatters: 'Card spend posts as an expense and a liability; the statement settlement clears it.', example: '2200 Corporate card payable.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:CreditCardPayableCurrent', match: 'close' }] }),
  c({ id: 'tie:DeferredRevenueLiability', label: 'Deferred revenue', group: 'revenue', parents: ['tie:CurrentLiability'], definition: 'Cash received or billed in advance of delivering a service; a contract liability under ASC 606.', whyItMatters: 'Annual subscriptions billed up front are earned monthly; recognizing them at billing overstates revenue.', example: '2300 Deferred revenue: a $120,000 annual subscription releases $10,000 per month.', synonyms: ['contract liability', 'unearned revenue'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:ContractWithCustomerLiabilityCurrent', match: 'exact' }], citations: ['asc606'] }),
  c({ id: 'tie:IntercompanyPayable', label: 'Intercompany payable', group: 'accounts', parents: ['tie:CurrentLiability', 'tie:ControlAccount'], definition: 'An amount this entity owes another entity in the same group.', whyItMatters: 'Must mirror the counterparty’s receivable; mismatches block consolidation.', example: '2400 Due to BWL-UK in the US ledger (denominated in GBP).', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:DueToRelatedPartiesCurrent', match: 'close' }], citations: ['asc810'] }),
  c({ id: 'tie:PayrollLiabilities', label: 'Payroll liabilities', group: 'accounts', parents: ['tie:CurrentLiability'], definition: 'Withholdings and employer taxes owed to authorities and benefit providers.', whyItMatters: 'Late remittance of payroll taxes carries penalties; balances should clear monthly.', example: '2500 Payroll taxes payable.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccruedPayrollTaxesCurrent', match: 'close' }] }),
  c({ id: 'tie:TaxesPayable', label: 'Taxes payable', group: 'accounts', parents: ['tie:CurrentLiability'], definition: 'Sales/VAT and income taxes owed.', whyItMatters: 'VAT on UK sales is collected for the tax authority and is never revenue.', example: '2600 VAT payable.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:TaxesPayableCurrent', match: 'close' }] }),
  c({ id: 'tie:LeaseLiability', label: 'Lease liability', group: 'leases', parents: ['tie:LiabilityAccount'], definition: 'The present value of remaining lease payments (ASC 842).', whyItMatters: 'Lease payments reduce the liability and accrete interest; the ROU asset amortizes in step.', example: '2410 Operating lease liability.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:OperatingLeaseLiability', match: 'exact' }], citations: ['asc842'] }),

  // equity
  c({ id: 'tie:ContributedCapital', label: 'Contributed capital', group: 'accounts', parents: ['tie:EquityAccount'], definition: 'Amounts shareholders invested: common stock and additional paid-in capital.', whyItMatters: 'Changes only with financing events; unexpected movement signals a mis-posting.', example: '3000 Common stock; 3100 APIC.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AdditionalPaidInCapital', match: 'close' }] }),
  c({ id: 'tie:RetainedEarnings', label: 'Retained earnings', group: 'accounts', parents: ['tie:EquityAccount'], definition: 'Cumulative profits not distributed; income and expense accounts close into it at year-end.', whyItMatters: 'The link between the income statement and the balance sheet.', example: '3200 Retained earnings.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:RetainedEarningsAccumulatedDeficit', match: 'exact' }] }),
  c({ id: 'tie:CumulativeTranslationAdjustment', label: 'Cumulative translation adjustment', group: 'fx', parents: ['tie:EquityAccount'], definition: 'The equity (OCI) account that absorbs differences from translating a foreign subsidiary’s statements into the reporting currency.', whyItMatters: 'Translation differences are not profit or loss under ASC 830; they go to CTA.', example: '3300 CTA moves when GBP strengthens against USD.', synonyms: ['CTA', 'translation reserve'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:AccumulatedOtherComprehensiveIncomeForeignCurrencyAdjustmentNetOfTax', match: 'close' }], citations: ['asc830'] }),

  // revenue
  c({ id: 'tie:SubscriptionRevenue', label: 'Subscription revenue', group: 'revenue', parents: ['tie:RevenueAccount'], definition: 'Revenue from access to software over time, recognized ratably over the service period.', whyItMatters: 'Over-time recognition: billing timing does not change monthly revenue.', example: '4000 Platform subscriptions.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:SubscriptionRevenue', match: 'close' }], citations: ['asc606'] }),
  c({ id: 'tie:ProductRevenue', label: 'Product revenue', group: 'revenue', parents: ['tie:RevenueAccount'], definition: 'Revenue from goods, recognized at the point control transfers to the customer.', whyItMatters: 'Cut-off: shipments after period end belong to the next period.', example: '4100 Hardware – sensor kits.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:RevenueFromContractWithCustomerProductMember', match: 'related' }], citations: ['asc606'] }),
  c({ id: 'tie:ServiceRevenue', label: 'Services revenue', group: 'revenue', parents: ['tie:RevenueAccount'], definition: 'Revenue from professional services such as installation and training.', whyItMatters: 'Often recognized as delivered; unbilled services may need a contract asset.', example: '4200 Professional services.', citations: ['asc606'] }),
  c({ id: 'tie:IntercompanyRevenue', label: 'Intercompany revenue', group: 'intercompany', parents: ['tie:RevenueAccount'], definition: 'Revenue earned from another entity in the same group.', whyItMatters: 'Eliminated on consolidation against the counterparty’s intercompany expense.', example: '4900 R&D services revenue (UK from US).', citations: ['asc810'] }),
  c({ id: 'tie:InterestIncome', label: 'Interest income', group: 'accounts', parents: ['tie:RevenueAccount'], definition: 'Income earned on cash balances and investments; presented in other income.', whyItMatters: 'Bank interest often appears on the statement before it is booked — a reconciling item.', example: '7000 Interest income.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:InvestmentIncomeInterest', match: 'close' }] }),
  c({ id: 'tie:FxGain', label: 'Foreign exchange gain/loss', group: 'fx', parents: ['tie:RevenueAccount'], definition: 'Gains and losses from remeasuring foreign-currency monetary items and from settling them (realized vs unrealized).', whyItMatters: 'Remeasurement differences go to profit or loss, unlike translation differences (CTA).', example: '7110 Unrealized FX gain/loss on a GBP-denominated payable.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:ForeignCurrencyTransactionGainLossBeforeTax', match: 'exact' }], citations: ['asc830'] }),

  // expenses
  c({ id: 'tie:CostOfRevenue', label: 'Cost of revenue', group: 'accounts', parents: ['tie:ExpenseAccount'], abstract: true, definition: 'Costs directly attributable to delivering revenue: hosting for customers, hardware cost, support staff.', whyItMatters: 'Misclassifying cost of revenue as operating expense inflates gross margin.', example: '5000 Hosting – production.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:CostOfRevenue', match: 'exact' }] }),
  c({ id: 'tie:HostingCost', label: 'Cloud hosting', group: 'accounts', parents: ['tie:CostOfRevenue'], definition: 'Infrastructure (compute, storage, network) used to run the product.', whyItMatters: 'Usually the fastest-growing cost line; spikes need a driver (usage, migration, price change).', example: '5000 Hosting – Cumulus Hosting monthly usage.', signals: { keywords: ['hosting', 'cloud', 'compute', 'cdn', 'storage', 'server', 'cumulus'], mcc: ['4816', '7379'] } }),
  c({ id: 'tie:HardwareCost', label: 'Hardware cost of goods sold', group: 'accounts', parents: ['tie:CostOfRevenue'], definition: 'The cost of sensor kits sold.', whyItMatters: 'Matches hardware revenue in the same period.', example: '5100 Hardware COGS.' }),
  c({ id: 'tie:OperatingExpense', label: 'Operating expense', group: 'accounts', parents: ['tie:ExpenseAccount'], abstract: true, definition: 'Costs of running the business that are not cost of revenue, presented by function (R&D, S&M, G&A).', whyItMatters: 'Opex is where most coding decisions — and most misclassifications — happen.', example: 'Rent, software, travel.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:OperatingExpenses', match: 'exact' }] }),
  c({ id: 'tie:CompensationExpense', label: 'Compensation', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Salaries, wages, payroll taxes and benefits.', whyItMatters: 'Largest expense; must include accrued days at month-end.', example: '6000 Salaries and wages.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:LaborAndRelatedExpense', match: 'close' }] }),
  c({ id: 'tie:RentExpense', label: 'Rent and occupancy', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Office rent, utilities and facilities.', whyItMatters: 'Rent is fixed and monthly — a missing or doubled month is easy to spot in flux.', example: '6100 Rent – Harborview Properties.', signals: { keywords: ['rent', 'properties', 'realty', 'lease', 'office space'], mcc: ['6513'] } }),
  c({ id: 'tie:SoftwareExpense', label: 'Software subscriptions', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'SaaS and licensed software used internally.', whyItMatters: 'Annual software contracts are prepaid and amortized; monthly ones are expensed as incurred.', example: '6150 Software – Tessellate CRM.', signals: { keywords: ['software', 'saas', 'subscription', 'license', 'crm', 'licence'], mcc: ['5734', '5817', '5818', '7372'] } }),
  c({ id: 'tie:MarketingExpense', label: 'Advertising and marketing', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Paid media, campaigns and brand spend.', whyItMatters: 'Advertising is expensed as incurred (ASC 720-35) — not prepaid unless it is a future event.', example: '6300 Advertising – Orbitron Ads.', signals: { keywords: ['ads', 'advertising', 'campaign', 'marketing', 'media buy'], mcc: ['7311'] } }),
  c({ id: 'tie:EventsExpense', label: 'Events and conferences', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Conference sponsorships, booths and event costs.', whyItMatters: 'Big one-off sponsorships create material flux that needs an explanation.', example: '6310 Events – ConfabCon headline sponsorship.', signals: { keywords: ['conference', 'summit', 'expo', 'sponsorship', 'booth', 'event'], mcc: ['7399', '7941'] } }),
  c({ id: 'tie:TravelExpense', label: 'Travel', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Airfare, lodging and ground transport for business travel.', whyItMatters: 'Card-heavy and policy-sensitive; receipts are required above thresholds.', example: '6400 Travel – Skylark Air.', signals: { keywords: ['airline', 'air', 'hotel', 'lodging', 'rail', 'taxi', 'rideshare', 'travel'], mcc: ['4511', '7011', '4121', '4112', '3000'] } }),
  c({ id: 'tie:MealsExpense', label: 'Meals and entertainment', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Business meals and client entertainment (partly non-deductible for tax).', whyItMatters: 'Tax treatment differs from other T&E, so classification matters.', example: '6410 Meals – Kettle & Crane Coffee.', signals: { keywords: ['restaurant', 'coffee', 'cafe', 'catering', 'bistro', 'kitchen'], mcc: ['5812', '5814', '5813'] } }),
  c({ id: 'tie:LegalFees', label: 'Legal fees', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Fees for outside counsel.', whyItMatters: 'Legal bills arrive late; month-end usually needs an accrual based on hours worked.', example: '6500 Legal – Atlas & Pike LLP.', signals: { keywords: ['llp', 'law', 'legal', 'attorney', 'counsel', 'solicitors'], mcc: ['8111'] } }),
  c({ id: 'tie:AuditTaxFees', label: 'Audit and tax fees', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'External audit, tax and accounting advisory fees.', whyItMatters: 'The annual audit fee is accrued over the year, not expensed when billed.', example: '6510 Audit – Brightline Audit Partners.', signals: { keywords: ['audit', 'cpa', 'accounting', 'tax advisory'], mcc: ['8931'] } }),
  c({ id: 'tie:OfficeExpense', label: 'Office and supplies', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Consumable office supplies and small items below the capitalization threshold.', whyItMatters: 'A frequent dumping ground for miscoded spend — large or recurring items here deserve a second look.', example: '6600 Office supplies – Verdant Office Supply.', signals: { keywords: ['office', 'supplies', 'stationery', 'paper', 'printer'], mcc: ['5111', '5943', '5044'] } }),
  c({ id: 'tie:TelecomExpense', label: 'Telecom and internet', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Phone, internet and network services for offices.', whyItMatters: 'Recurring monthly; missing bills are an accrual signal.', example: '6650 Telecom – Redwood Fiber.', signals: { keywords: ['telecom', 'fiber', 'internet', 'broadband', 'phone', 'wireless'], mcc: ['4814', '4899'] } }),
  c({ id: 'tie:InsuranceExpense', label: 'Insurance', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Premiums for business insurance, usually prepaid annually and amortized.', whyItMatters: 'Paid annually, expensed monthly — a prepaid schedule must exist.', example: '6700 Insurance – Fieldstone Mutual.', signals: { keywords: ['insurance', 'mutual', 'underwriters', 'premium'], mcc: ['6300'] } }),
  c({ id: 'tie:DepreciationExpense', label: 'Depreciation expense', group: 'assets', parents: ['tie:OperatingExpense'], definition: 'The periodic allocation of a fixed asset’s cost over its useful life.', whyItMatters: 'Straight-line depreciation is predictable — any deviation means the schedule and ledger disagree.', example: '6800 Depreciation.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:Depreciation', match: 'exact' }], citations: ['asc360'] }),
  c({ id: 'tie:BankFees', label: 'Bank fees', group: 'accounts', parents: ['tie:OperatingExpense'], definition: 'Charges by banks for accounts, wires and services.', whyItMatters: 'They appear on the bank statement first and must be booked to reconcile cash.', example: '6900 Bank fees – monthly service charge.', signals: { keywords: ['service charge', 'bank fee', 'wire fee', 'account fee', 'analysis charge'] } }),
  c({ id: 'tie:IntercompanyExpense', label: 'Intercompany expense', group: 'intercompany', parents: ['tie:OperatingExpense'], definition: 'Expense charged by another entity in the same group.', whyItMatters: 'Eliminated against the counterparty’s intercompany revenue on consolidation.', example: '6950 R&D services from BWL-UK.', citations: ['asc810'] }),
  c({ id: 'tie:IncomeTaxExpense', label: 'Income tax expense', group: 'accounts', parents: ['tie:ExpenseAccount'], definition: 'Current and deferred income taxes.', whyItMatters: 'Usually provided for quarterly; monthly estimates smooth the result.', example: '8000 Income tax expense.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:IncomeTaxExpenseBenefit', match: 'exact' }] }),
  c({ id: 'tie:SuspenseAccount', label: 'Suspense account', group: 'accounts', parents: ['tie:CurrentAsset'], definition: 'A temporary holding account for amounts whose classification is unknown.', whyItMatters: 'A suspense balance at close means work is unfinished; it should be zero.', example: '1999 Suspense – unclassified.', synonyms: ['clearing account', 'uncategorized'] }),

  // ------------------------------------------------------------------ statements
  c({ id: 'tie:FinancialStatement', label: 'Financial statement', group: 'statements', parents: ['tie:Thing'], abstract: true, definition: 'A structured report of financial position or performance prepared from the ledger.', whyItMatters: 'The close exists to produce reliable statements for management, lenders and auditors.', example: 'Balance sheet at 30 Sep 2026.', citations: ['conceptual-framework'] }),
  c({ id: 'tie:BalanceSheet', label: 'Balance sheet', group: 'statements', parents: ['tie:FinancialStatement'], definition: 'Assets, liabilities and equity at a point in time; always satisfies Assets = Liabilities + Equity.', whyItMatters: 'If it does not balance, something did not post correctly.', example: 'Consolidated balance sheet of Bramblewood Labs at 30 Sep 2026.', synonyms: ['statement of financial position'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:StatementOfFinancialPositionAbstract', match: 'exact' }], citations: ['usgaap-taxonomy'] }),
  c({ id: 'tie:IncomeStatement', label: 'Income statement', group: 'statements', parents: ['tie:FinancialStatement'], definition: 'Revenue and expenses over a period, ending in net income.', whyItMatters: 'Flux analysis explains how this period differs from the last and from budget.', example: 'September 2026 P&L.', synonyms: ['P&L', 'profit and loss', 'statement of operations'], mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:IncomeStatementAbstract', match: 'exact' }], citations: ['usgaap-taxonomy'] }),
  c({ id: 'tie:CashFlowStatement', label: 'Cash flow statement', group: 'statements', parents: ['tie:FinancialStatement'], definition: 'Cash movements split into operating, investing and financing activities.', whyItMatters: 'Explains why cash moved differently from profit.', example: 'Indirect method starting from net income.', mappings: [{ scheme: 'US-GAAP', ref: 'us-gaap:StatementOfCashFlowsAbstract', match: 'exact' }] }),
  c({ id: 'tie:TrialBalance', label: 'Trial balance', group: 'statements', parents: ['tie:Thing'], definition: 'A list of every account with its debit or credit balance at a date; total debits must equal total credits.', whyItMatters: 'The starting point for statements and the first check that the ledger is internally consistent.', example: 'BWL-US trial balance at 30 Sep 2026.', synonyms: ['TB'], citations: ['pacioli1494'] }),
  c({ id: 'tie:FinancialStatementLineItem', label: 'Financial statement line item', group: 'statements', parents: ['tie:Thing'], definition: 'A caption on a statement (e.g. "Accrued liabilities") to which accounts roll up, mapped to an XBRL US-GAAP concept.', whyItMatters: 'The mapping from accounts to lines is what turns a ledger into statements and XBRL.', example: 'BS.CL.ACCRUED maps to us-gaap:AccruedLiabilitiesCurrent.', mappings: [{ scheme: 'US-GAAP', ref: 'xbrli:item', match: 'related' }], citations: ['usgaap-taxonomy'] }),
  c({ id: 'tie:ClosePackage', label: 'Close package', group: 'close', parents: ['tie:Thing'], definition: 'The signed bundle produced at the end of the close: trial balances, statements, flux commentary, reconciliation status and sign-offs.', whyItMatters: 'It is what management and auditors rely on; once final it is immutable.', example: 'September 2026 close package v1, SHA-256 sealed.' }),

  // ------------------------------------------------------------------ entries
  c({ id: 'tie:JournalEntry', label: 'Journal entry', group: 'entries', parents: ['tie:EconomicEvent'], definition: 'A dated record of an economic event in the general ledger, made of two or more lines whose debits equal their credits.', whyItMatters: 'Every number in the statements is the sum of journal entries; each must balance, be approved by someone other than its preparer, and post to an open period.', example: 'JE-2026-09-0042: debit 6500 Legal fees $13,640, credit 2110 Accrued expenses $13,640.', synonyms: ['JE', 'entry', 'journal'], rea: 'Event', mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:entryHeader', match: 'exact' }], citations: ['xbrl-gl', 'pacioli1494', 'ellerman2014'], properties: [{ name: 'entityId', label: 'Entity', range: 'ref', refClass: 'tie:LegalEntity', required: true, description: 'Legal entity whose ledger the entry posts to' }, { name: 'periodKey', label: 'Period', range: 'string', required: true, description: 'Accounting period YYYY-MM' }, { name: 'postingDate', label: 'Posting date', range: 'date', required: true, description: 'Date within the period' }, { name: 'entryType', label: 'Entry type', range: 'enum', enumValues: ['standard', 'adjusting', 'accrual', 'reversing', 'recurring', 'reclass', 'elimination', 'fx_revaluation', 'opening', 'closing'], required: true, description: 'Kind of entry' }, { name: 'memo', label: 'Memo', range: 'text', required: true, description: 'Plain-English description of the event' }, { name: 'lines', label: 'Lines', range: 'ref', refClass: 'tie:JournalLine', many: true, required: true, description: 'Two or more balanced lines' }] }),
  c({ id: 'tie:JournalLine', label: 'Journal line', group: 'entries', parents: ['tie:Thing'], definition: 'One side of a journal entry: an account, a debit or a credit amount, and dimension tags.', whyItMatters: 'Lines are where classification happens — the account and department chosen decide where the number appears.', example: 'Debit 6500 Legal fees $13,640, department G&A.', synonyms: ['entry line', 'posting line'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:entryDetail', match: 'exact' }], citations: ['xbrl-gl'], properties: [{ name: 'accountCode', label: 'Account', range: 'string', required: true, description: 'Account code to post to' }, { name: 'debitMinor', label: 'Debit', range: 'money', required: true, description: 'Debit amount (0 if credit)' }, { name: 'creditMinor', label: 'Credit', range: 'money', required: true, description: 'Credit amount (0 if debit)' }, { name: 'department', label: 'Department', range: 'string', description: 'Department code if the account requires it' }, { name: 'memo', label: 'Line memo', range: 'text', description: 'Optional line description' }] }),
  c({ id: 'tie:Debit', label: 'Debit', group: 'entries', parents: ['tie:Thing'], definition: 'The left side of an entry: increases assets and expenses, decreases liabilities, equity and revenue.', whyItMatters: 'Debit and credit are directions, not good or bad; balance is the invariant.', example: 'Paying rent: debit Rent expense.', mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:debitCreditCode = D', match: 'exact' }], citations: ['pacioli1494'] }),
  c({ id: 'tie:Credit', label: 'Credit', group: 'entries', parents: ['tie:Thing'], definition: 'The right side of an entry: increases liabilities, equity and revenue, decreases assets and expenses.', whyItMatters: 'Every debit needs equal credits; the pair records both sides of one event (REA duality).', example: 'Paying rent: credit Cash.', mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:debitCreditCode = C', match: 'exact' }], citations: ['pacioli1494', 'mccarthy1982'] }),
  c({ id: 'tie:StandardEntry', label: 'Standard entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'A routine entry generated by day-to-day activity (bills, invoices, payments).', whyItMatters: 'Not allowed after soft close — late routine activity must wait for the next period or become an adjustment.', example: 'Posting a vendor bill.' }),
  c({ id: 'tie:AdjustingEntry', label: 'Adjusting entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'A period-end entry that brings balances to their correct amount (accruals, deferrals, corrections).', whyItMatters: 'Adjustments are where judgment lives and where auditors look first.', example: 'Recording a missed prepaid amortization.', synonyms: ['AJE', 'adjustment'], citations: ['pcaob-as2401'] }),
  c({ id: 'tie:AccrualEntry', label: 'Accrual entry', group: 'accruals', parents: ['tie:AdjustingEntry'], definition: 'An adjusting entry recognizing an expense (or revenue) earned but not yet invoiced, normally reversed on day one of the next period.', whyItMatters: 'Without it, expenses land in the month the bill arrives instead of the month the work happened (cut-off).', example: 'Accrue September legal fees $13,640; auto-reverse 1 Oct.', citations: ['conceptual-framework', 'asc450'] }),
  c({ id: 'tie:ReversingEntry', label: 'Reversing entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'An entry that exactly mirrors a prior posted entry, swapping debits and credits, to cancel it.', whyItMatters: 'Posted entries are never edited; reversal is the only correction and keeps the audit trail intact.', example: 'Reverse the September legal accrual on 1 October.', synonyms: ['reversal'], citations: ['asc250'] }),
  c({ id: 'tie:RecurringEntry', label: 'Recurring entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'An entry generated on a schedule with the same structure each period (rent, amortization, depreciation).', whyItMatters: 'If a recurring entry silently fails to run, the balance drifts — schedules must be reconciled to the ledger.', example: 'Monthly prepaid amortization of $4,500.' }),
  c({ id: 'tie:ReclassEntry', label: 'Reclassification entry', group: 'entries', parents: ['tie:AdjustingEntry'], definition: 'An entry that moves an amount from one account (or department) to another without changing totals.', whyItMatters: 'Fixes classification errors — the classification assertion.', example: 'Move $6,880 of hosting from Office supplies to Cloud hosting.', synonyms: ['reclass'] }),
  c({ id: 'tie:EliminationEntry', label: 'Elimination entry', group: 'intercompany', parents: ['tie:AdjustingEntry'], definition: 'A consolidation entry removing intercompany balances and transactions so the group reports only dealings with outsiders.', whyItMatters: 'Without eliminations, group revenue and receivables are inflated by internal trades.', example: 'Eliminate $186,102 of US-UK R&D service revenue and expense.', citations: ['asc810'] }),
  c({ id: 'tie:FxRevaluationEntry', label: 'FX revaluation entry', group: 'fx', parents: ['tie:AdjustingEntry'], definition: 'An entry remeasuring foreign-currency monetary balances at the closing rate, recognizing unrealized gain or loss.', whyItMatters: 'Monetary items must be carried at the closing rate (ASC 830-20-35-1).', example: 'Revalue the GBP intercompany payable at 1.3412 USD/GBP.', citations: ['asc830'] }),
  c({ id: 'tie:OpeningEntry', label: 'Opening balance entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'The entry that loads balances migrated from a prior system.', whyItMatters: 'Opening balances are audited once and then become history.', example: 'Opening balances at 31 Aug 2025.' }),
  c({ id: 'tie:ClosingEntry', label: 'Closing entry', group: 'entries', parents: ['tie:JournalEntry'], definition: 'The year-end entry that moves the year’s income and expense balances into retained earnings, leaving them at zero for the new year.', whyItMatters: 'It transfers profit; it is not income or expense of the month it is dated in, so period income statements and variance analysis leave it out (AX-FS-01).', example: 'FY2025 close at 31 Dec 2025: income and expense accounts to 3200 Retained earnings.', synonyms: ['year-end close', 'closing entry'], citations: ['conceptual-framework'] }),

  // ------------------------------------------------------------------ periods
  c({ id: 'tie:AccountingPeriod', label: 'Accounting period', group: 'periods', parents: ['tie:Thing'], definition: 'The span of time (here a calendar month) that entries post to and statements report on.', whyItMatters: 'Cut-off: every event belongs to exactly one period; posting into the wrong one misstates two months.', example: '2026-09 runs from 1 to 30 September 2026.', synonyms: ['period', 'month', 'fiscal period'], mappings: [{ scheme: 'XBRL-GL', ref: 'gl-cor:periodCoveredStart / periodCoveredEnd', match: 'close' }], properties: [{ name: 'periodKey', label: 'Key', range: 'string', required: true, description: 'YYYY-MM' }, { name: 'status', label: 'Status', range: 'enum', enumValues: ['future', 'open', 'soft_closed', 'locked'], required: true, description: 'Lifecycle state' }] }),
  c({ id: 'tie:OpenPeriod', label: 'Open period', group: 'periods', parents: ['tie:AccountingPeriod'], definition: 'A period accepting all entries.', whyItMatters: 'Only open periods take routine activity.', example: 'September during the first days of October.' }),
  c({ id: 'tie:SoftClosedPeriod', label: 'Soft-closed period', group: 'periods', parents: ['tie:AccountingPeriod'], definition: 'A period closed to routine activity (subledgers cut off) but still accepting approved adjusting entries.', whyItMatters: 'Lets the team finish adjustments while preventing late routine postings from moving the numbers.', example: 'September after WD+3, when only adjustments are allowed.', synonyms: ['soft close'] }),
  c({ id: 'tie:LockedPeriod', label: 'Locked period', group: 'periods', parents: ['tie:AccountingPeriod'], definition: 'A period closed to all posting (hard close). Reopening requires a Controller and a documented reason.', whyItMatters: 'Once statements are issued, the numbers behind them must not change silently.', example: 'August 2026 after its close package was finalized.', synonyms: ['hard close', 'closed period'] }),
  c({ id: 'tie:FiscalYear', label: 'Fiscal year', group: 'periods', parents: ['tie:Thing'], definition: 'The 12-month reporting year (here the calendar year).', whyItMatters: 'Budgets, year-to-date figures and retained-earnings rollover follow the fiscal year.', example: 'FY2026 = Jan–Dec 2026.' }),
];
